"""ViBioMIR Standalone Distributed Cloud Crawler for Kaggle.
Shard: misc1 (30,792 targets, method: direct)
"""

import asyncio
import base64
import hashlib
import html
import json
import os
import random
import re
import subprocess
import sys
import time
import unicodedata
import urllib.parse
import zlib
from collections import Counter, defaultdict
from pathlib import Path

# Step 1: Install required dependencies
print("[Setup] Installing curl_cffi, trafilatura, orjson...")
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "curl_cffi", "trafilatura", "orjson", "beautifulsoup4"], check=False)

import orjson
import trafilatura
from bs4 import BeautifulSoup
from curl_cffi.requests import AsyncSession

# Step 2: Unpack embedded targets
EMBEDDED_TARGETS_B64 = """"""

TARGETS_FILE = Path("/kaggle/working/targets.tsv") if Path("/kaggle/working").exists() else Path("targets.tsv")
DOCS_OUT = Path("/kaggle/working/docs.jsonl") if Path("/kaggle/working").exists() else Path("docs.jsonl")
STATE_OUT = Path("/kaggle/working/state.tsv") if Path("/kaggle/working").exists() else Path("state.tsv")

print(f"[Setup] Decompressing embedded targets to {TARGETS_FILE}...")
raw_tsv = zlib.decompress(base64.b64decode(EMBEDDED_TARGETS_B64))
TARGETS_FILE.write_bytes(raw_tsv)

# Step 3: Cleaning & Quality Gate
BLOCK_PAGE_RE = re.compile(
    r"attention required|just a moment|access denied|enable javascript and cookies|checking your browser|"
    r"kh\xf4ng t\xecm th\u1ea5y trang|trang b\u1ea1n t\xecm ki\u1ebfm kh\xf4ng|the content on this page is not available in|"
    r"404 not found|page not found|\u9875\u9762\u4e0d\u5b58\u5728|\u60a8\u8bbf\u95ee\u7684\u9875\u9762\u4e0d\u5b58\u5728",
    re.IGNORECASE,
)
MIN_WEB_CHARS = 200

def junk_reason(text: str, dup_count: int = 1) -> str | None:
    n = len((text or "").strip())
    if n < MIN_WEB_CHARS:
        return "too_short"
    if n < 3000 and BLOCK_PAGE_RE.search(text[:800]):
        return "blocked_or_404"
    if dup_count >= 3:
        return "duplicate_template"
    return None

def extract_article(raw_html: str) -> tuple[str, str]:
    if not raw_html:
        return "", ""
    try:
        soup = BeautifulSoup(raw_html[:15000], "html.parser")
        title = soup.title.string.strip() if soup.title and soup.title.string else ""
    except Exception:
        title = ""
    try:
        text = trafilatura.extract(raw_html, include_comments=False, include_tables=True, no_fallback=False, favor_precision=True) or ""
    except Exception:
        text = ""
    if not text:
        try:
            soup = BeautifulSoup(raw_html, "html.parser")
            for t in soup(["script", "style", "nav", "footer", "header", "aside"]):
                t.decompose()
            text = " ".join(soup.stripped_strings)
        except Exception:
            text = ""
    return title, text

# Step 4: Asynchronous Crawler
WAYBACK_TEMPLATE = "https://web.archive.org/web/9999id_/{url}"

class CloudCrawler:
    def __init__(self, method: str = "direct", concurrency: int = 16):
        self.method = method
        self.concurrency = concurrency
        self.sem_global = asyncio.Semaphore(concurrency)
        self.host_sems = defaultdict(lambda: asyncio.Semaphore(6))
        self.dead_hosts = set()
        self.consec_block = Counter()
        self.counts = Counter()
        self.out_f = open(DOCS_OUT, "ab")
        self.state_f = open(STATE_OUT, "a", encoding="utf-8")
        self.started = time.time()
        self.text_seen = Counter()

    def record(self, doc_id: int, host: str, outcome: str, detail: str = ""):
        self.counts[outcome] += 1
        self.state_f.write(f"{doc_id}\t{self.method}\t{outcome}\t{detail}\n")
        self.state_f.flush()

    async def fetch(self, session: AsyncSession, url: str) -> tuple[int, str]:
        if self.method in ("wayback", "dual"):
            wayback_url = WAYBACK_TEMPLATE.format(url=url)
            try:
                r = await session.get(wayback_url, timeout=12.0, allow_redirects=True, headers={"Accept-Language": "vi,en;q=0.8"})
                if r.status_code == 200 and len(r.text) >= 200:
                    return 200, r.text
            except Exception:
                pass
            if self.method == "wayback":
                return 404, ""

        # Direct fetch fallback with Chrome TLS impersonation
        try:
            r = await session.get(url, timeout=12.0, allow_redirects=True, headers={"Accept-Language": "vi,en;q=0.8"})
            if r.status_code == 200 and len(r.text) >= 200:
                return 200, r.text
            return r.status_code, ""
        except Exception:
            return 0, ""

    async def handle_target(self, session: AsyncSession, doc_id: int, url: str, host: str):
        if host in self.dead_hosts:
            return
        async with self.sem_global, self.host_sems[host]:
            if host in self.dead_hosts:
                return
            await asyncio.sleep(0.2 + random.random() * 0.3)
            status, raw_html = await self.fetch(session, url)
            
            if status in (404, 410):
                self.record(doc_id, host, "no_snapshot" if self.method == "wayback" else "http_error", str(status))
                return
            if status == 429:
                self.record(doc_id, host, "rate_limited", "429")
                await asyncio.sleep(2.0)
                return
            if status != 200 or not raw_html:
                self.record(doc_id, host, "http_error", str(status))
                return

            title, text = extract_article(raw_html)
            text_hash = hashlib.md5(text.encode("utf-8", "ignore")).digest()
            self.text_seen[text_hash] += 1
            
            why = junk_reason(text, dup_count=self.text_seen[text_hash])
            if why:
                self.record(doc_id, host, why)
                if why in ("blocked_or_404", "duplicate_template"):
                    self.consec_block[host] += 1
                    if self.consec_block[host] >= 10:
                        print(f"[Host Blocked] Cutting off host {host} after 10 consecutive blocks.")
                        self.dead_hosts.add(host)
                return

            self.consec_block[host] = 0
            rec = {"id": doc_id, "url": url, "title": title, "text": text, "ok": 1, "source": self.method}
            self.out_f.write(orjson.dumps(rec) + b"\n")
            self.out_f.flush()
            self.record(doc_id, host, "ok", f"len={len(text)}")

    async def run(self):
        print(f"[Run] Loading targets from {TARGETS_FILE}...")
        targets = []
        with open(TARGETS_FILE, encoding="utf-8") as f:
            for line in f:
                parts = line.strip().split("\t")
                if len(parts) >= 2:
                    did = int(parts[0])
                    url = parts[1]
                    host = urllib.parse.urlsplit(url).netloc.lower()
                    targets.append((did, url, host))

        print(f"[Run] Loaded {len(targets):,} targets. Starting async session (concurrency={self.concurrency})...")
        async with AsyncSession(impersonate="chrome124", verify=False) as session:
            tasks = [self.handle_target(session, did, url, host) for did, url, host in targets]
            
            # Progress reporting
            total = len(tasks)
            done = 0
            for chunk_start in range(0, total, 500):
                chunk = tasks[chunk_start:chunk_start + 500]
                await asyncio.gather(*chunk)
                done += len(chunk)
                elapsed = time.time() - self.started
                print(f"[Progress] {done:,}/{total:,} ({100*done/total:.1f}%) in {elapsed:.1f}s | Stats: {dict(self.counts)}", flush=True)

        self.out_f.close()
        self.state_f.close()
        print(f"[Complete] Finished shard in {time.time() - self.started:.1f}s. Final counts: {dict(self.counts)}")

if __name__ == "__main__":
    crawler = CloudCrawler()
    asyncio.run(crawler.run())
